<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/audit.php'; requireRole('admin');
$hospitals = $pdo->query("SELECT id, hospital_name FROM hospitals WHERE status = 'active' ORDER BY hospital_name")->fetchAll(PDO::FETCH_ASSOC);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $hospitalId = filter_input(INPUT_POST, 'hospital_id', FILTER_VALIDATE_INT); $officerId = filter_input(INPUT_POST, 'officer_id', FILTER_VALIDATE_INT); $username = trim($_POST['username'] ?? ''); $email = trim($_POST['email'] ?? ''); $name = trim($_POST['full_name'] ?? ''); $password = $_POST['password'] ?? '';
    if (!verifyCsrfToken($_POST['csrf_token'] ?? null) || !$hospitalId || ($officerId === false || $officerId === null) || $name === '' || $username === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) { flash('danger', 'Complete the officer and hospital details.'); }
    elseif (!$officerId && strlen($password) < 8) { flash('danger', 'New officer passwords must be at least 8 characters.'); }
    else { try { if ($officerId) { $check = $pdo->prepare("SELECT u.id FROM users u JOIN roles r ON r.id = u.role_id WHERE u.id = :user_id AND r.role_name = 'receptionist' LIMIT 1"); $check->execute([':user_id' => $officerId]); if (!$check->fetchColumn()) { throw new RuntimeException('Front Desk Officer account not found.'); } $update = $pdo->prepare('UPDATE users SET full_name = :full_name, hospital_id = :hospital_id WHERE id = :user_id'); $update->execute([':full_name' => $name, ':hospital_id' => $hospitalId, ':user_id' => $officerId]); logAudit('STAFF_HOSPITAL_ASSIGNED', 'user', $officerId, 'Front Desk Officer assignment updated.'); } else { $role = $pdo->prepare("SELECT id FROM roles WHERE role_name = 'receptionist' LIMIT 1"); $role->execute(); $insert = $pdo->prepare('INSERT INTO users (role_id, hospital_id, username, email, full_name, password_hash, status) VALUES (:role_id, :hospital_id, :username, :email, :full_name, :password_hash, \'active\')'); $insert->execute([':role_id' => $role->fetchColumn(), ':hospital_id' => $hospitalId, ':username' => $username, ':email' => $email, ':full_name' => $name, ':password_hash' => password_hash($password, PASSWORD_DEFAULT)]); logAudit('FRONT_DESK_OFFICER_CREATED', 'user', (int) $pdo->lastInsertId(), 'Front Desk Officer account created.'); } flash('success', $officerId ? 'Officer assignment updated.' : 'Front Desk Officer account created.'); redirect('front_desk_officers.php'); } catch (Throwable $exception) { flash('danger', $exception instanceof RuntimeException ? $exception->getMessage() : 'Could not save the officer. Username or email may already exist.'); } }
}
$officers = $pdo->query("SELECT u.id, u.username, u.email, u.full_name, h.hospital_name FROM users u JOIN roles r ON r.id = u.role_id LEFT JOIN hospitals h ON h.id = u.hospital_id WHERE r.role_name = 'receptionist' ORDER BY u.username")->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'Front Desk Officers'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">Administration</p><h1 class="h2">Front Desk Officers</h1></div></div><div class="row g-4"><div class="col-lg-5"><div class="setup-card"><h2 class="h5">Create officer account</h2><?php if (!$hospitals): ?><p class="text-muted">Add an active hospital first.</p><?php else: ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="officer_id" value="0"><label class="form-label">Full name</label><input class="form-control mb-3" name="full_name" required><label class="form-label">Username</label><input class="form-control mb-3" name="username" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Password</label><input class="form-control mb-3" type="password" name="password" minlength="8" required><label class="form-label">Assigned hospital</label><select class="form-select mb-3" name="hospital_id" required><option value="">Select hospital</option><?php foreach ($hospitals as $hospital): ?><option value="<?= (int) $hospital['id'] ?>"><?= e($hospital['hospital_name']) ?></option><?php endforeach; ?></select><button class="btn btn-primary">Create officer</button></form><?php endif; ?></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Current assignments</h2><div class="table-responsive"><table class="table"><thead><tr><th>Officer</th><th>Email</th><th>Hospital</th></tr></thead><tbody><?php foreach ($officers as $officer): ?><tr><td><?= e($officer['full_name'] ?: $officer['username']) ?></td><td><?= e($officer['email']) ?></td><td><?= e($officer['hospital_name'] ?: 'Unassigned') ?></td></tr><?php endforeach; ?><?php if (!$officers): ?><tr><td colspan="3" class="text-muted">No Front Desk Officers found.</td></tr><?php endif; ?></tbody></table></div></div></div></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>
